    return documents;
  }, [drafts, snapshot?.catalog, proposalSearchDocument, proposalSearchId]);
  useEffect(() => { search.sync(searchDocuments); }, [search, searchDocuments]);
  useEffect(() => () => search.dispose(), [search]);
