    this.timers.set(key, setTimeout(() => { this.timers.delete(key); void this.refresh(key); }, this.pollMs));
  }
  async submit(key: string) {
    const entry = this.entry(key);
    if (editUnsettled(entry) || !entry.prompt.trim() || this.stopped) return;
    this.patch(key, { pending: true, error: undefined, run: undefined, request: undefined });
    try {
      const capture = await this.client.capture(entry.target.canvasId, entry.target.documentId, entry.target.nodeId);
      if (this.stopped) return;
      const request: EditDiagramInput = { ...capture, nodeId: entry.target.nodeId, prompt: entry.prompt.trim(), requestId: crypto.randomUUID() };
      // Retain the exact request before sending: a lost response must never start a second generation.
      this.patch(key, { request });
      this.accept(key, await this.client.start(request));
    } catch (error) { this.patch(key, { error: String(error) }); }
    finally { this.patch(key, { pending: false }); }
  }
  async retry(key: string) {
    const entry = this.entry(key);
    if (entry.pending || this.stopped) return;
    if (!entry.request) return this.submit(key);
    if (entry.run && entry.run.status !== 'awaiting-acknowledgement') return this.refresh(key);
    this.patch(key, { pending: true, error: undefined });
    try { this.accept(key, await this.client.start(entry.request)); }
    catch (error) { this.patch(key, { error: String(error) }); }
    finally { this.patch(key, { pending: false }); }
  }
  async refresh(key: string) {
    const run = this.entry(key)?.run;
    if (!run || this.polling.has(key) || this.stopped) return;
    this.polling.add(key);
    try {
      const next = await this.client.status(run.runId);
      // A cancel/retry response may already have moved this run forward while the read was in flight.
      if (this.entry(key)?.run === run) this.accept(key, next);
    } catch (error) { if (this.entry(key)?.run === run) this.patch(key, { error: `Could not refresh progress: ${String(error)}` }); }
    finally {
      this.polling.delete(key);
      if (this.entry(key)?.run !== run && !this.timers.has(key)) this.schedule(key);
    }
  }
  async cancel(key: string) {
    const entry = this.entry(key);
    if (entry.pending || entry.run?.status !== 'generating' || this.stopped) return;
    this.patch(key, { pending: true });
    try { this.accept(key, await this.client.cancel(entry.run.runId)); }
    catch (error) { this.patch(key, { error: String(error) }); }
    finally { this.patch(key, { pending: false }); }
  }
  dispose() {
    this.stopped = true;
    for (const timer of this.timers.values()) clearTimeout(timer);
    this.timers.clear();
  }
}

import { AgentContext, type AgentContextSnapshot } from '../../../domain/core/agents/agentContext';
import { randomUUID } from 'node:crypto';
import { CanvasHistory } from '../../../domain/core/diagrams/canvasHistory';
import type { DiagramService, DiagramRevisionResult } from '../../../domain/core/diagrams/diagramService';
import type { LiveDocumentSnapshot } from '../../../domain/mapping/agent/contracts';
import type { DiagramEditRun, DiagramRevisionApplication, EditDiagramInput } from '../../../domain/mapping/agent/diagramEdit';
import { findBox } from '../../../domain/mapping/workspace/canvasDisplayNode';

export interface DiagramEditCanvasPort {
  snapshot(sessionId: string): Promise<LiveDocumentSnapshot>;
  apply(sessionId: string, input: DiagramRevisionApplication): Promise<{ version: number; unresolvedEdgeIds: string[] }>;
}
interface Run {
  agentContext?: AgentContextSnapshot;
  input: EditDiagramInput;
  signature: string;
  state: DiagramEditRun;
  abort: AbortController;
  revision?: DiagramRevisionResult;
  pending?: Promise<void>;
}

/** A request owns both generation and installation; retries never rerun the model. */
export class DiagramEditService {
  private runs = new Map<string, Run>();
  private requests = new Map<string, string>();
  constructor(private readonly diagrams: DiagramService, private readonly canvas: DiagramEditCanvasPort) {}

  start(input: EditDiagramInput, suppliedContext?: AgentContextSnapshot): DiagramEditRun {
    const agentContext = suppliedContext ? AgentContext.fromSnapshot(suppliedContext).toSnapshot() : undefined;
    if (input.agentContextId && !agentContext) throw Error('AGENT_CONTEXT_NOT_FOUND: resolve context before starting the edit');
    const key = JSON.stringify([input.sessionId, input.requestId]);
    const signature = JSON.stringify({ input, agentContextHash: agentContext?.contentHash });
    const existing = this.requests.get(key);
    if (existing) {
      const run = this.runs.get(existing)!;
      if (run.signature !== signature) throw Error('REQUEST_ID_CONFLICT: edit request differs');
      if (run.state.status === 'awaiting-acknowledgement' && !run.pending) this.launch(run, () => this.apply(run));
      return structuredClone(run.state);
    }
    if (this.runs.size >= 500) throw Error('Diagram edit run capacity reached; restart the backend');
    const run: Run = { agentContext, input: structuredClone(input), signature, abort: new AbortController(), state: {
      runId: `diagram-edit-${randomUUID()}`, status: 'generating', nodeId: input.nodeId, baseRevisionId: input.baseRevisionId
    } };
    this.runs.set(run.state.runId, run); this.requests.set(key, run.state.runId);
    this.launch(run, () => this.generate(run));
    return structuredClone(run.state);
  }
  get(id: string) {
    const run = this.runs.get(id); if (!run) throw Error('Diagram edit run not found');
    return structuredClone(run.state);
  }
  cancel(id: string) {
    const run = this.runs.get(id); if (!run) throw Error('Diagram edit run not found');
    // Once application is dispatched its outcome can be unknown. Never call it cancelled.
    if (run.state.status === 'generating') {
      run.abort.abort(); run.state.status = 'cancelled'; run.state.message = 'Cancelled before application';
    }
    return structuredClone(run.state);
  }
  private launch(run: Run, work: () => Promise<void>) {
    run.pending = work().catch(error => {
      if (run.abort.signal.aborted && run.state.status !== 'applying') { run.state.status = 'cancelled'; return; }
      const message = error instanceof Error ? error.message : String(error);
      run.state.status = run.state.status === 'applying' && /CANVAS_TIMEOUT|CANVAS_UNAVAILABLE|PERSISTENCE_PENDING/.test(message)
        ? 'awaiting-acknowledgement' : message.includes('VERSION_CONFLICT') ? 'conflict' : 'failed';
      run.state.error = message;
    }).finally(() => { run.pending = undefined; });
  }
  private async generate(run: Run) {
    const { input, abort } = run;
    const snapshot = await this.canvas.snapshot(input.sessionId);
    abort.signal.throwIfAborted();
    if (snapshot.version !== input.expectedVersion) throw Error('VERSION_CONFLICT: read the canvas again');
    const box = input.nodeId.startsWith('grid:') && findBox(snapshot.document.scene.root, input.nodeId.slice(5));
    if (!box || box.kind !== 'diagram') throw Error('Expected diagram GridBox');
    const base = snapshot.document.scene.contents[box.contentId];
    if (base.revisionId !== input.baseRevisionId) throw Error('VERSION_CONFLICT: diagram base is no longer current');
    if (!snapshot.history) throw Error('Canvas history is required for diagram generation');
    // Validated portable history imports the exact browser-issued revision identities.
    new CanvasHistory(snapshot.document, snapshot.canvas, snapshot.history, 'current');
    const lines = base.content.ascii.split('\n');
    run.revision = await this.diagrams.generate({ input: { id: base.id, structureKind: base.content.structure.kind,
      source: base.sourceContext.binding, evidence: base.sourceContext.evidence },
      instruction: input.prompt, agentContext: run.agentContext, baseRevisionId: base.revisionId,
      context: { diagram: base, selection: { startLine: 1, endLine: lines.length, startColumn: 1,
        endColumn: Math.max(1, ...lines.map(line => line.length)) }, connections: snapshot.document.edges }
    }, { signal: abort.signal, onProgress: message => { if (run.state.status === 'generating') run.state.message = message; } });
    abort.signal.throwIfAborted();
    run.state.generated = { diagramId: run.revision.diagram.diagramId, revisionId: run.revision.revision.id,
      ascii: run.revision.diagram.content.ascii };
    await this.apply(run);
  }
  private async apply(run: Run) {
    run.state.status = 'applying'; delete run.state.error;
    const revision = run.revision!.revision, input = run.input;
    // The controller checks both versions at the mutation boundary, after generation.
    const result = await this.canvas.apply(input.sessionId, { requestId: run.state.runId,
      expectedVersion: input.expectedVersion, nodeId: input.nodeId, baseRevisionId: input.baseRevisionId, revision });
    run.state.result = { diagramId: revision.diagramId, previousRevisionId: input.baseRevisionId,
      revisionId: revision.id, documentVersion: result.version, unresolvedEdgeIds: result.unresolvedEdgeIds };
    run.state.status = 'completed'; run.state.message = 'Diagram revision installed and workspace persisted';
  }
  dispose() { for (const run of this.runs.values()) this.cancel(run.state.runId); }
}

import type { DeepReadonly } from '../immutability';
import { validateDiagramJumps, type DiagramJump } from './diagramJump';
import { buildDiagramContent, type DiagramContent } from './diagramContent';
import { validateDiagramLocalMappings } from './diagramMappings';
import { mappingsForSelection } from './diagramSelection';
import { asciiSha256 } from './asciiSha256';
import type { DiagramElementMapping } from '../records/domain';
import type { CorpusBinding, BuiltInDomainProfileId } from '../profiles/domainProfile';
import type { ProjectRepresentationEvidenceRecord } from '../representations/projectCatalog';

export interface DiagramSourceBinding {
  sourceId: string;
  repositoryIdentity: string;
  corpus: CorpusBinding;
  domainProfileId: BuiltInDomainProfileId;
}
export type DiagramSourceContext = DeepReadonly<{
  binding?: DiagramSourceBinding;
  contentHash: string;
  mappings: readonly DiagramElementMapping[];
  evidence: Record<string, ProjectRepresentationEvidenceRecord>;
}>;
/** Repository-independent diagram, shared by canvas, persistence, and agents. */
export interface Diagram {
  /** Stable service identity; id remains the local canvas content key. */
  readonly diagramId: string;
  readonly revisionId: string;
  readonly id: string;
  readonly revision: number;
  readonly content: DeepReadonly<DiagramContent>;
  readonly sourceContext: DeepReadonly<DiagramSourceContext>;
  readonly jumps?: DeepReadonly<DiagramJump[]>;
}
export interface DiagramInput {
  id: string; revision: number; ascii: string; structureKind?: 'diagram' | 'tree';
  mappings?: readonly DiagramElementMapping[];
  evidence?: DiagramSourceContext['evidence'];
  source?: DiagramSourceBinding;
  jumps?: readonly DiagramJump[];
}
export function validateSourceBinding(binding: DiagramSourceBinding): void {
  if (!binding || typeof binding.sourceId !== 'string' || !binding.sourceId || binding.sourceId.length > 200
    || typeof binding.repositoryIdentity !== 'string' || !binding.repositoryIdentity
    || !['source-code','document'].includes(binding.domainProfileId) || !binding.corpus
    || !['git-worktree','filesystem-documents'].includes(binding.corpus.kind)
    || typeof binding.corpus.root !== 'string' || !/^(?:\/|[A-Za-z]:[\\/])/.test(binding.corpus.root)
    || (binding.domainProfileId === 'source-code') !== (binding.corpus.kind === 'git-worktree')) throw new Error('Invalid diagram source binding');
}
export function validateDiagram(diagram: Diagram): void {
  if (diagram?.content && (!diagram.diagramId || !diagram.revisionId))
    throw new Error('Diagram storage migration required: saved diagrams lack service identities. Run the offline diagram identity migration before loading this store.');
  if (!diagram || typeof diagram.diagramId !== 'string' || !diagram.diagramId.startsWith('diagram-') || typeof diagram.revisionId !== 'string' || !diagram.revisionId.startsWith('diagram-revision-') || typeof diagram.id !== 'string' || !diagram.id || !Number.isInteger(diagram.revision) || diagram.revision < 0 || !diagram.content) throw new Error('Invalid diagram');
  if (['ascii','mappings','diagramContent','structureKind'].some(key => Object.hasOwn(diagram,key))) throw new Error('Diagram data must live in content and sourceContext');
  const { content, sourceContext: source } = diagram;
  const canonical = buildDiagramContent(content.ascii, `${diagram.id}:${diagram.revision}`, content.structure.kind, content.structure.kind === 'tree' ? content.structure.parserVersion : undefined);
  if (JSON.stringify(content) !== JSON.stringify(canonical)) throw new Error('Invalid diagram content revision or parsed structure');
  if (!source || !source.evidence || !Array.isArray(source.mappings) || source.contentHash !== asciiSha256(content.ascii)) throw new Error('Diagram source context does not match content');
  if (source.binding) validateSourceBinding(source.binding);
  validateDiagramJumps(content, diagram.jumps);
  validateDiagramLocalMappings(content.ascii, source.mappings);
  for (const [id, entry] of Object.entries(source.evidence)) {
    if (entry?.sourceId && source.binding && entry.sourceId !== source.binding.sourceId) throw new Error('Evidence belongs to another diagram source');
    if (!entry || entry.id !== id || typeof entry.label !== 'string' || !Array.isArray(entry.sourceRanges)) throw new Error('Invalid diagram evidence');
    for (const range of entry.sourceRanges) {
      if (!range || typeof range.id !== 'string' || typeof range.path !== 'string' || range.path.startsWith('/') || range.path.split(/[\\/]/).includes('..')
        || !Number.isInteger(range.startLine) || range.startLine < 1 || !Number.isInteger(range.endLine) || range.endLine < range.startLine
        || !Array.isArray(range.originalLines) || range.originalLines.length !== range.endLine - range.startLine + 1 || range.originalLines.some((line: unknown) => typeof line !== 'string')) throw new Error('Invalid diagram evidence range');
    }
  }
  for (const mapping of source.mappings) {
    const range = source.evidence[mapping.entityId]?.sourceRanges[mapping.sourceRangeIndex];
    if (!range || mapping.sourceRangeId && mapping.sourceRangeId !== range.id) throw new Error('Mapping references unknown diagram evidence');
  }
}
/** All mapping/evidence joins live here; callers receive derived, read-only results. */
export function diagramSource(diagram: Diagram) {
  return queryDiagramSourceContext(diagram.sourceContext);
}
export function queryDiagramSourceContext(context: DiagramSourceContext) {
  const evidenceFor = (mapping: DiagramElementMapping) => {
    const entity = context.evidence[mapping.entityId];
    const range = entity?.sourceRanges[mapping.sourceRangeIndex];
    return { mapping, entity, range, binding: context.binding };
  };
  return {
    context,
    mappings: () => context.mappings,
    forSelection: (rect: Parameters<typeof mappingsForSelection>[1]) => mappingsForSelection(context.mappings, rect).map(evidenceFor),
    entries: () => context.mappings.map(evidenceFor),
    search: (query: string) => {
      const q = query.toLowerCase();
      return context.mappings.map(evidenceFor).filter(({mapping,entity,range}) => [mapping.entityId,entity?.label,range?.path,range?.symbol].some(value=>value?.toLowerCase().includes(q)));
    }
  };
}
export function sourceBindingFromLocation(location: { checkoutRoot: string; repositoryIdentity: string; domainProfileId?: BuiltInDomainProfileId; corpus?: CorpusBinding; gitRevision?: string }): DiagramSourceBinding {
  const corpus = location.corpus ?? { kind: 'git-worktree' as const, root: location.checkoutRoot, ...(location.gitRevision ? {revision:location.gitRevision} : {}) };
  return { sourceId: `source-${asciiSha256(`${corpus.kind}:${corpus.root}`).slice(0,24)}`, repositoryIdentity: location.repositoryIdentity,
    corpus, domainProfileId: location.domainProfileId ?? 'source-code' };
}

import { RevisionedDiagramService, type DiagramService } from '../../core/diagrams/diagramService';

import {
  layoutScene,
  updateGridBox,
  type Diagram,
  type GridBox,
  type LineGridScene
} from "../../core/diagrams/lineGrid";
import { MAPPING_POC_A_NODES, MAPPING_POC_GRAPH_A } from "../selection/mappingPoc";
import { MAPPING_POC_A_SECTIONS, type MappingPocASection } from "../selection/mappingPocOverlays";

export interface MappingGridDocument {
  jumps?: import('../../core/diagrams/canvasJump').CanvasJump[];
  scene: LineGridScene;
  edges: import('../../core/diagrams/diagramConnection').DiagramConnection[];
  sections: Readonly<Record<string, readonly MappingPocASection[]>>;
}

export function initialMappingGrid(): MappingGridDocument {
  const evidence = Object.fromEntries(MAPPING_POC_A_NODES.map(node => [node.id, { id: node.id, handle: node.id, label: node.label, category: "operation" as const, summary: node.label, sourceRanges: node.sourceRanges.map((range,i) => ({ ...range, id: `${node.id}-range-${i}`, originalLines: Array.from({length:range.endLine-range.startLine+1},()=>"") })) }]));
  const content = new RevisionedDiagramService().create({ evidence,
    id: "overview", revision: 0, ascii: MAPPING_POC_GRAPH_A,
    mappings: MAPPING_POC_A_NODES.flatMap((node) => node.sourceRanges.map((_, sourceRangeIndex) => ({
      id: `${node.id}:range-${sourceRangeIndex + 1}`, entityId: node.id, sourceRangeIndex,
      ...node.head
    })))
  }).diagram;
  return {
    edges: [],
    scene: { contents: { overview: content, "overview-summary": new RevisionedDiagramService().create({ id: "overview-summary", revision: 0, ascii: "[Current LLM prompt stack]" }).diagram },
      root: { id: "root", kind: "container", position: { column: 0, row: 0 }, collapsed: false,
        layout: { collisionPolicy: "push-right", gap: 3 }, children: [{ id: "overview", kind: "diagram",
          position: { column: 0, row: 0 }, collapsed: false, contentId: "overview", collapsedContentId: "overview-summary" }] }
    },
    sections: { overview: MAPPING_POC_A_SECTIONS }
  };
}

export function insertGridDiagram(document: MappingGridDocument, parentId: string, box: GridBox, content: Diagram, diagrams: DiagramService = new RevisionedDiagramService()): MappingGridDocument {
  const summaryId = `${content.id}-summary`;
  let scene: LineGridScene = { ...document.scene, contents: { ...document.scene.contents, [content.id]: content,
    [summaryId]: diagrams.create({ id: summaryId, revision: 0, ascii: `[${content.content.ascii.split("\n")[0].trim().slice(0, 36)}]` }).diagram } };
  scene = updateGridBox(scene, parentId, (parent) => {
    if (parent.kind !== "container") throw new Error("Diagrams must be inserted into a container");
    return { ...parent, collapsed: false, children: [...parent.children, { ...box, collapsedContentId: summaryId }] };
  });
  return { ...document, scene: layoutScene(scene, box.id), sections: { ...document.sections, [content.id]: [] } };
}

import type { StorageChange } from '../../../../domain/core/storage/storageService';
import type { MappingWorkspaceSnapshot } from '../../../../domain/mapping/workspace/mappingWorkspace';
import type { WorkspaceRecordState } from '../../../../domain/mapping/workspace/workspaceRecords';
import { RecordStorage } from './recordStorage';

/** One worker per opened workspace; no worker construction in a store() call. */
export class WorkspaceStorage {
  records?: RecordStorage;
  private worker?: Worker;
  private id = 0;
  private requests = new Map<number, { resolve(value: unknown): void; reject(error: Error): void }>();
  private endpoint = `${import.meta.env.BASE_URL.replace(/\/$/, '')}/api/mapping/workspace/records`;
  private ready?: Promise<MappingWorkspaceSnapshot | null>;
  private ensureWorker() {
    if (this.worker) return this.worker;
    const worker = this.worker = new Worker(new URL('./workspaceStorage.worker.ts', import.meta.url), { type: 'module' });
    worker.onmessage = ({ data }) => {
      const request = this.requests.get(data.id); if (!request) return;
      this.requests.delete(data.id);
      if (data.error) request.reject(Error(data.error)); else request.resolve(data.result);
    };
    const fail = () => {
      this.requests.forEach(r => r.reject(Error('Workspace worker stopped; reload to reconnect'))); this.requests.clear();
      worker.terminate(); this.worker = undefined;
    };
    worker.onerror = fail; worker.onmessageerror = fail;
    return worker;
  }
  private request<T>(input: Record<string, unknown>): Promise<T> {
    return new Promise((resolve, reject) => {
      const id = ++this.id;
      this.requests.set(id, { resolve: value => resolve(value as T), reject });
      try { this.ensureWorker().postMessage({ ...input, id, endpoint: new URL(this.endpoint, location.href).href }); }
      catch (e) { this.requests.delete(id); reject(e); }
    });
  }
  load() {
    return this.ready ??= this.request<{ state: WorkspaceRecordState; workspace: MappingWorkspaceSnapshot | null }>({ type: 'load' }).then(({ state, workspace }) => {
      this.records = new RecordStorage(state, { write: batch => this.request({ type: 'write', batch }) }); return workspace;
    }).catch(error => { this.ready = undefined; throw error; });
  }
  async project(snapshot: MappingWorkspaceSnapshot) { return this.request<StorageChange[]>({ type: 'project', snapshot }); }
  async save(snapshot: MappingWorkspaceSnapshot) {
    await this.load(); await this.records!.flush();
    const changes = await this.project(snapshot);
    await this.records!.commit(changes);
  }

  async restore() {
    await this.records?.flush();
    this.records?.dispose(); this.ready = undefined;
    return this.load();
  }
  async flush() { await this.load(); await this.records!.flush(); }
  dispose() {
    this.records?.dispose(); this.worker?.terminate(); this.worker = undefined;
    this.requests.forEach(r => r.reject(Error('Storage closed'))); this.requests.clear();
  }
}

import type { MappingPocGridRect } from '../selection/mappingPoc';
import type { ProjectionSelectionResult } from '../../core/diagrams/diagramProjection';
import type { PanelContent } from '../code-panel/codePanel';
