  representationId: string; name: string; revisionId: string; savedName: string; savedScene: string; savedEdges?: string;
  document: MappingGridDocument; canvas: MappingCanvasState; viewport?: CanvasTransform;
}
export interface MappingWorkspaceSnapshot {
  transfers?: import('../../core/diagrams/canvasTransfer').CanvasTransfer[];
  schemaVersion: 3; projectId: string; activeDocumentId?: string; documents: MappingDocumentSnapshot[];
}

import { CanvasHistory, type CanvasHistoryRecord, type ResolvedCanvasDocument } from './canvasHistory';
import type { DiagramView } from './diagramRevisionEditor';
import { prepareCanvasTransfer, prepareTransferNavigation, transferBoundary, type CanvasTransfer, type TransferInput, type PreparedCanvasTransfer, type TransferState } from './canvasTransfer';


/** Runtime handle. Neither it nor the service belongs in a saved canvas. */
export interface CanvasEditingContext { readonly contextId: string }
export interface CanvasContextState {
  checkpointId: string;
  document: import('./canvasHistory').CanvasDocument;
  view: unknown;
  canUndo: boolean;
  canRedo: boolean;
}

/** Canvas controllers coordinate edits; this boundary owns history and its storage. */
export interface CanvasHistoryService {
  prepareTransfer(context: CanvasEditingContext, input: TransferInput, destination?: CanvasEditingContext): PreparedCanvasTransfer;
  transferBoundary(context: CanvasEditingContext, transaction: CanvasTransfer, canvasId: string, redo?: boolean): boolean;
  prepareTransferNavigation(source: CanvasEditingContext, destination: CanvasEditingContext, transaction: CanvasTransfer, redo?: boolean): { source: TransferState; destination: TransferState; transaction: CanvasTransfer };
  openContext(document: ResolvedCanvasDocument, view: unknown, history?: CanvasHistoryRecord): CanvasEditingContext;
  state(context: CanvasEditingContext): CanvasContextState;
  resolve(context: CanvasEditingContext, diagramId: string): DiagramView;
  document(context: CanvasEditingContext): ResolvedCanvasDocument;
  append(context: CanvasEditingContext, document: ResolvedCanvasDocument, view: unknown, correspondence?: ReadonlyMap<string, string>): void;
  navigate(context: CanvasEditingContext, redo?: boolean): boolean;
  reset(context: CanvasEditingContext): void;
  /** Portable transport adapters; callers must not interpret diagram revision tables. */
  exportContext(context: CanvasEditingContext): CanvasHistoryRecord;
  persistenceChanges(context: CanvasEditingContext, since?: number): import("./canvasHistory").HistoryChanges;
  retireTransactions(context: CanvasEditingContext, ids: ReadonlySet<string>): void;
  forkContext(context: CanvasEditingContext, view: unknown): CanvasHistoryRecord;
  adopt(context: CanvasEditingContext, proposed: CanvasHistoryRecord): void;
}

export class DefaultCanvasHistoryService implements CanvasHistoryService {
  constructor(private readonly validation: import('./canvasHistory').HistoryValidation = 'all') {}
  // Object handles isolate two viewers of the same persisted context, and allow GC on close.
  private readonly contexts = new WeakMap<CanvasEditingContext, CanvasHistory>();

  openContext(document: ResolvedCanvasDocument, view: unknown, record?: CanvasHistoryRecord): CanvasEditingContext {
    const history = new CanvasHistory(document, view, record, this.validation);
    const context = Object.freeze({ contextId: history.contextId });
    this.contexts.set(context, history);
    return context;
  }
  private history(context: CanvasEditingContext) {
    const history = this.contexts.get(context);
    if (!history) throw new Error('Unknown diagram editing context');
    return history;
  }
  state(context: CanvasEditingContext): CanvasContextState {
    const history = this.history(context), head = history.head;
    return { checkpointId: head.id, document: head.document, view: head.view, canUndo: history.canUndo, canRedo: history.canRedo };
  }
  resolve(context: CanvasEditingContext, diagramId: string) {
    const history = this.history(context);
    return history.diagrams.resolve(history.contextId, diagramId);
  }
  document(context: CanvasEditingContext) { return this.history(context).document(); }
  append(context: CanvasEditingContext, document: ResolvedCanvasDocument, view: unknown, correspondence?: ReadonlyMap<string, string>) {
    this.history(context).append(document, view, correspondence);
  }
  navigate(context: CanvasEditingContext, redo = false) {
    const linked = this.history(context).navigationTransactionId(redo);
    if (linked) throw Error('Use workspace undo/redo for a canvas transfer.');
    return !!this.history(context).navigate(redo);
  }
  prepareTransfer(context: CanvasEditingContext, input: TransferInput, destination?: CanvasEditingContext) {
    return prepareCanvasTransfer(this.history(context).export(), input, destination ? this.history(destination).export() : undefined);
  }
  transferBoundary(context: CanvasEditingContext, transaction: CanvasTransfer, canvasId: string, redo = false) {
    return transferBoundary({ headId: this.history(context).headId }, transaction, canvasId, redo);
  }
  prepareTransferNavigation(source: CanvasEditingContext, destination: CanvasEditingContext, transaction: CanvasTransfer, redo = false) {
    return prepareTransferNavigation(this.history(source).export(), this.history(destination).export(), transaction, redo);
  }
  reset(context: CanvasEditingContext) { this.history(context).reset(); }
  persistenceChanges(context: CanvasEditingContext, since?: number) { return this.history(context).persistenceChanges(since); }
  retireTransactions(context: CanvasEditingContext, ids: ReadonlySet<string>) { this.history(context).retireTransactions(ids); }
  exportContext(context: CanvasEditingContext) { return this.history(context).export(); }
  forkContext(context: CanvasEditingContext, view: unknown) { return this.history(context).fork(view); }
  adopt(context: CanvasEditingContext, proposed: CanvasHistoryRecord) { this.history(context).adopt(proposed); }
}

import type { StorageChange } from '../../../../domain/core/storage/storageService';
import { documentPrefix, historyChanges, type WorkspaceIndex } from '../../../../domain/mapping/workspace/workspaceRecords';
import type { CanvasTransfer } from '../../../../domain/core/diagrams/canvasTransfer';
import type { StoredCanvasSnapshot } from '../../../../domain/core/diagrams/canvasHistory';
import type { CanvasDraft, CanvasWorkspace } from './canvasWorkspace';
import type { CanvasSession } from './canvasSession';
import type { SourcePaneViewState } from '../source-pane/sourcePaneViewState';
import type { RecordStorage } from './recordStorage';

/** Owns the translation from live owners to persisted records, never a global snapshot. */
export class WorkspacePersistence {
  private cursors = new WeakMap<CanvasSession, number>();
  private known = new Map<string, CanvasDraft>();
  private subscriptions: (() => void)[] = [];
  private activeDocumentId?: string;
  private transfers: CanvasTransfer[] = [];
  private paused = false;
  constructor(private readonly workspace: CanvasWorkspace, private readonly storage: RecordStorage,
    private readonly projectId: string, private readonly view: SourcePaneViewState) {
    const index = storage.get<WorkspaceIndex>('workspace');
    this.activeDocumentId = index?.activeDocumentId; this.transfers = index?.transfers ?? [];
    this.subscriptions.push(workspace.onPersist(ids => this.sync(ids)), view.subscribe(id => this.syncView(id)));
    this.sync([...new Set([...(index?.documentIds ?? []), ...Object.keys(workspace.store.getState().drafts)])]);
  }
  setPaused(paused: boolean) { this.paused = paused; }
  update(activeDocumentId: string | undefined, transfers: CanvasTransfer[]) {
    this.activeDocumentId = activeDocumentId; this.transfers = transfers;
    if (!this.paused) this.storage.batch([this.index()]);
  }
  private index(): StorageChange {
    const ids = Object.keys(this.workspace.store.getState().drafts);
    return { key: 'workspace', value: { projectId: this.projectId, documentIds: ids,
      activeDocumentId: this.activeDocumentId && ids.includes(this.activeDocumentId) ? this.activeDocumentId : ids[0], transfers: this.transfers } satisfies WorkspaceIndex };
  }
  sync(ids = [...new Set([...this.known.keys(), ...Object.keys(this.workspace.store.getState().drafts)])]) {
    if (this.paused) return;
    const drafts = this.workspace.store.getState().drafts, changes: StorageChange[] = [];
    for (const id of ids) {
      const draft = drafts[id], prior = this.known.get(id), prefix = documentPrefix(id);
      if (!draft) {
        for (const key of this.storage.keys()) if (key.startsWith(prefix)) changes.push({ key, delete: true });
        this.known.delete(id); continue;
      }
      const { representationId: savedRepresentationId, name, hidden, savedName, savedScene, savedEdges, revisionId } = draft;
      changes.push({ key: prefix + 'metadata', value: { representationId: id, savedRepresentationId, name, hidden } },
        { key: prefix + 'baseline', value: { savedName, savedScene, savedEdges, revisionId } });
      const cursor = this.cursors.get(draft.session), delta = draft.session.controller.persistenceChanges(cursor);
      if (cursor === undefined) {
        // Import/reset can replace a canvas's history graph under the same ID.
        // Remove the old graph in the same atomic batch as its replacement.
        const retained = new Set(historyChanges(id, delta).map(change => change.key));
        for (const key of this.storage.keys()) {
          if ((key.startsWith(prefix + 'revision/') || key.startsWith(prefix + 'checkpoint/')) && !retained.has(key)) changes.push({ key, delete: true });
        }
      }
      for (const change of historyChanges(id, delta)) {
        // A new runtime session may attach to history already present in storage.
        // Revision IDs are immutable; checkpoints may have retired transfer links.
        if (cursor === undefined && 'value' in change && this.storage.get(change.key)) {
          if (change.key.startsWith(prefix + 'revision/')) continue;
          if (change.key.startsWith(prefix + 'checkpoint/') && this.storage.get<StoredCanvasSnapshot>(change.key)?.transactionId === (change.value as StoredCanvasSnapshot).transactionId) continue;
        }
        changes.push(change);
      }
      this.cursors.set(draft.session, delta.sequence);
      const canvas = draft.session.controller.getSnapshot().canvas;
      changes.push({ key: prefix + 'canvas', value: { ...canvas, display: this.view.captureDisplay(id, canvas.display) } });
      if (prior?.viewport !== draft.viewport || !prior) {
        const viewport = this.view.captureCamera(id, draft.viewport);
        if (viewport) changes.push({ key: prefix + 'viewport', value: viewport });
      }
      this.known.set(id, draft);
    }
    changes.push(this.index()); this.storage.batch(changes);
  }
  private syncView(id: string) {
    if (this.paused) return;
    const draft = this.workspace.store.getState().drafts[id]; if (!draft) return;
    const prefix = documentPrefix(id), canvas = draft.session.controller.getSnapshot().canvas;
    const viewport = this.view.captureCamera(id, draft.viewport);
    this.storage.batch([{ key: prefix + 'canvas', value: { ...canvas, display: this.view.captureDisplay(id, canvas.display) } },
      ...(viewport ? [{ key: prefix + 'viewport', value: viewport }] : [])]);
  }
  dispose() { this.subscriptions.forEach(off => off()); }
}

